using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Security.Cryptography;using Mono.Cecil;using Mono.Cecil.Cil;
public static class SimplePatch {
 static JavaScriptSerializer j=new JavaScriptSerializer(){MaxJsonLength=int.MaxValue};static string Hash(string p){using(var s=File.OpenRead(p))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 static IEnumerable<TypeDefinition> All(TypeDefinition t){yield return t;foreach(var n in t.NestedTypes)foreach(var x in All(n))yield return x;}
 static string Structure(AssemblyDefinition a){return string.Join("\n",a.MainModule.Types.SelectMany(All).SelectMany(t=>new[]{"T:"+t.FullName+":"+t.Attributes+":"+t.BaseType}.Concat(t.Fields.Select(f=>"F:"+f.FullName+":"+f.Attributes)).Concat(t.Methods.Select(m=>"M:"+m.FullName+":"+m.Attributes)).Concat(t.Interfaces.Select(x=>"I:"+x.InterfaceType.FullName))));}
 public static void Run(string root,string target){var rows=((object[])j.DeserializeObject(File.ReadAllText(Path.Combine(root,"candidates.json")))).Cast<Dictionary<string,object>>().ToArray();var reports=new List<object>();var patchedMethods=new List<object>();var resolver=new DefaultAssemblyResolver();resolver.AddSearchDirectory(target);resolver.AddSearchDirectory(Path.Combine(Path.GetDirectoryName(root),"metadata-assemblies"));resolver.AddSearchDirectory(Path.Combine(Path.GetDirectoryName(target),"../../Library/ScriptAssemblies"));var rp=new ReaderParameters(){AssemblyResolver=resolver};Directory.CreateDirectory(Path.Combine(root,"baseline"));Directory.CreateDirectory(Path.Combine(root,"patched"));
 foreach(var group in rows.GroupBy(x=>(string)x["assembly"])){
 string source=Path.Combine(target,group.Key+".dll"),baseline=Path.Combine(root,"baseline",group.Key+".dll"),output=Path.Combine(root,"patched",group.Key+".dll");File.Copy(source,baseline,true);string baselineHash=Hash(baseline);using(var a=AssemblyDefinition.ReadAssembly(baseline,rp)){string before=Structure(a);var refs=a.MainModule.AssemblyReferences.Select(x=>x.FullName).ToArray();int count=0;foreach(var row in group){var t=a.MainModule.Types.SelectMany(All).Single(x=>x.FullName==(string)row["type"]);var m=t.Methods.Single(x=>x.FullName==(string)row["signature"]);var kind=(string)row["kind"];FieldDefinition f=null;if(row["field"]!=null){var fr=(Dictionary<string,object>)row["field"];f=t.Fields.Single(x=>x.Name==(string)fr["name"]&&x.FieldType.FullName==(string)fr["type"]);if(f.IsStatic)throw new Exception("Unexpected static field");}var prior=m.HasBody?m.Body.Instructions.Select(x=>x.ToString()).ToArray():new string[0];var body=new MethodBody(m){InitLocals=false,MaxStackSize=2};m.Body=body;var il=body.GetILProcessor();
 if(kind=="instance_field_getter"){if(m.IsStatic||m.Parameters.Count!=0||m.ReturnType.FullName!=f.FieldType.FullName)throw new Exception("Getter identity mismatch");il.Emit(OpCodes.Ldarg_0);il.Emit(OpCodes.Ldfld,f);}
 else if(kind=="instance_scalar_field_setter"){if(m.IsStatic||m.Parameters.Count!=1||m.Parameters[0].ParameterType.FullName!=f.FieldType.FullName||m.ReturnType.FullName!="System.Void")throw new Exception("Setter identity mismatch");il.Emit(OpCodes.Ldarg_0);il.Emit(OpCodes.Ldarg_1);il.Emit(OpCodes.Stfld,f);}
 else if(kind=="integer_constant"){if(m.Parameters.Count!=0)throw new Exception("Constant params");long value=Convert.ToInt64(row["constant"]);if(m.ReturnType.FullName=="System.Int64"||m.ReturnType.FullName=="System.UInt64")il.Emit(OpCodes.Ldc_I8,value);else il.Emit(OpCodes.Ldc_I4,unchecked((int)value));}
 else throw new Exception("Unsupported kind");il.Emit(OpCodes.Ret);patchedMethods.Add(new{assembly=group.Key,type=t.FullName,signature=m.FullName,kind=kind,nativeRva=row["rva"],nativeBytes=row["nativeBytes"],beforeIL=prior,afterIL=m.Body.Instructions.Select(x=>x.OpCode+" "+(x.Operand==null?"":x.Operand.ToString())).ToArray()});count++;}
 if(before!=Structure(a))throw new Exception("Unexpected structural modification");if(!refs.SequenceEqual(a.MainModule.AssemblyReferences.Select(x=>x.FullName)))throw new Exception("Assembly references changed");if(a.MainModule.AssemblyReferences.Any(x=>x.Name==a.Name.Name))throw new Exception("Self assembly reference");a.Write(output);reports.Add(new{assembly=a.Name.FullName,sourceTargetPath=source,baselineSha256=baselineHash,outputSha256=Hash(output),patchedMethods=count,structuralComparison="identical types, fields, signatures, modifiers, interfaces",assemblyReferences="unchanged; no self-reference",sourceTargetUnchanged=baselineHash==Hash(source)});}}
 File.WriteAllText(Path.Combine(root,"patch-manifest.json"),j.Serialize(reports));File.WriteAllText(Path.Combine(root,"method-patches.json"),j.Serialize(patchedMethods));Console.WriteLine("Patched "+patchedMethods.Count+" methods in "+reports.Count+" candidate assemblies; target unchanged.");}
}
